// src/parsers/catalog.ts
// AUTO-GENERATED Minimal Perfect Hash Function (👑 Lemire MPHF / FNV-1a) Catalog Engine
// 9342 LaTeX symbols, operators, bare functions, Typst aliases, and Unicode glyphs with zero collisions and O(1) lookup.

import { getMacroSignature, MacroSignature } from "./macro_dictionary";
export type { MacroSignature };

export const DOMAIN_CORE = 1 << 0;              // 1: Universal math & calculus basics
export const DOMAIN_CALCULUS = 1 << 1;          // 2: Differentials, limits, integrals
export const DOMAIN_LINEAR_ALGEBRA = 1 << 2;    // 4: Matrices, rank, trace, span, eigenvalues
export const DOMAIN_QUANTUM = 1 << 3;           // 8: Bra-ket, operators, spin, commutators
export const DOMAIN_PHYSICS = 1 << 4;           // 16: Physics vectors, tensors, coordinate frames
export const DOMAIN_UNITS = 1 << 5;             // 32: SI units and physical dimensions
export const DOMAIN_ABSTRACT_ALGEBRA = 1 << 6; // 64: Groups, rings, fields, hom, ker, aut
export const DOMAIN_ML_STATS = 1 << 7;          // 128: relu, gelu, softmax, distributions
export const DOMAIN_ALL = 0xFFFFFFFF;

// Dialect Bitmasks (10 Concurrent Mathematical Platforms in Base-2 Binary)
export const DIALECT_LATEX     = 0b00_0000_0001; // 1 << 0: LaTeX / MathJax 4 core
export const DIALECT_TYPST     = 0b00_0000_0010; // 1 << 1: Typst Math
export const DIALECT_ASCIIMATH = 0b00_0000_0100; // 1 << 2: AsciiMath
export const DIALECT_MATLAB    = 0b00_0000_1000; // 1 << 3: MATLAB / GNU Octave
export const DIALECT_PYTHON    = 0b00_0001_0000; // 1 << 4: Python / SymPy
export const DIALECT_WOLFRAM   = 0b00_0010_0000; // 1 << 5: Wolfram Language
export const DIALECT_JULIA     = 0b00_0100_0000; // 1 << 6: Julia (Scientific Computing)
export const DIALECT_LEAN4     = 0b00_1000_0000; // 1 << 7: Lean 4 (Theorem Proving)
export const DIALECT_R         = 0b01_0000_0000; // 1 << 8: R (Statistical Computing)
export const DIALECT_MAXIMA    = 0b10_0000_0000; // 1 << 9: Maxima (CAS)
export const DIALECT_ALL       = 0b11_1111_1111; // 1023: Universal across all 10 dialects

// 16 Frequency-Ranked Numeric Role IDs (Roadmap 2.3.1)
export const ROLE_FUNCTION   = 0;  // sin, cos, ln, exp, det (highest frequency bare words)
export const ROLE_OPERATOR   = 1;  // +, -, *, /, sum, int
export const ROLE_RELATION   = 2;  // =, <=, >=, !=, in, subset
export const ROLE_CONSTANT   = 3;  // pi, e, infty, hbar
export const ROLE_PARAMETER  = 4;  // alpha, beta, theta, x, y
export const ROLE_DERIVATIVE = 5;  // partial, d/dx
export const ROLE_DELIMITER  = 6;  // (, ), [, ], {, }, |
export const ROLE_STRUCTURAL = 7;  // mat, pmat, frac, sqrt
export const ROLE_UNIT       = 8;  // m, s, kg, V, A
export const ROLE_VARIABLE   = 9;  // bare variables / symbols
export const ROLE_ARROW      = 10; // ->, =>, to, implies
export const ROLE_SET        = 11; // R, N, Z, cup, cap
export const ROLE_DOT        = 12; // cdot, times, ox
export const ROLE_TRANSFORM  = 13; // T, dag, -1
export const ROLE_SPACING    = 14; // quad, qquad, ,, :, ;
export const ROLE_ARITHMETIC = 15; // +-, -+, o+

export function getActiveDialects(options?: {
  dialectLatex?: boolean;
  dialectTypst?: boolean;
  dialectAsciiMath?: boolean;
  dialectMatlab?: boolean;
  dialectPython?: boolean;
  dialectWolfram?: boolean;
  dialectJulia?: boolean;
  dialectLean4?: boolean;
  dialectR?: boolean;
  dialectMaxima?: boolean;
}): number {
  if (!options) return DIALECT_ALL;
  let mask = DIALECT_ALL;
  if (options.dialectLatex === false) mask &= ~DIALECT_LATEX;
  if (options.dialectTypst === false) mask &= ~DIALECT_TYPST;
  if (options.dialectAsciiMath === false) mask &= ~DIALECT_ASCIIMATH;
  if (options.dialectMatlab === false) mask &= ~DIALECT_MATLAB;
  if (options.dialectPython === false) mask &= ~DIALECT_PYTHON;
  if (options.dialectWolfram === false) mask &= ~DIALECT_WOLFRAM;
  if (options.dialectJulia === false) mask &= ~DIALECT_JULIA;
  if (options.dialectLean4 === false) mask &= ~DIALECT_LEAN4;
  if (options.dialectR === false) mask &= ~DIALECT_R;
  if (options.dialectMaxima === false) mask &= ~DIALECT_MAXIMA;
  return mask >>> 0;
}

export function isNativeInDialect(entry: CatalogEntry, dialectBit: number): boolean {
  if (entry.dialects === undefined || entry.dialects === DIALECT_ALL) return true;
  return (entry.dialects & dialectBit) !== 0;
}

export const ARG_TYPE_NONE = 0; // 0b00
export const ARG_TYPE_MATH = 1; // 0b01
export const ARG_TYPE_TEXT = 2; // 0b10
export const ARG_TYPE_RAW  = 3; // 0b11
export type NumericArgType = 0 | 1 | 2 | 3;

// 26 Canonical MathJax CHTML Structural Layout Tag IDs (0x00 to 0x1F)
export const TAG_NONE         = 0x00; // Ordinary inline leaf/glyph (<mjx-c>, <mjx-mi>, <mjx-mo>)
// Fraction & Division
export const TAG_MFRAC        = 0x01; // <mjx-mfrac> (outer fraction container)
export const TAG_FRAC         = 0x02; // <mjx-frac> (inner fraction element)
export const TAG_NUM          = 0x03; // <mjx-num> (numerator slot)
export const TAG_DEN          = 0x04; // <mjx-den> (denominator slot)
export const TAG_DBOX         = 0x05; // <mjx-dbox> (denominator wrapper box)
export const TAG_DTABLE       = 0x06; // <mjx-dtable> (denominator table)
export const TAG_LINE         = 0x07; // <mjx-line> / <mjx-dline> (fraction rule bar)
export const TAG_DSTRUT       = 0x08; // <mjx-dstrut> / <mjx-nstrut> (vertical layout strut)
// Limits & Stacks
export const TAG_MUNDEROVER   = 0x09; // <mjx-munderover> (dual-limit container)
export const TAG_MUNDER       = 0x0A; // <mjx-munder> (lower-limit container)
export const TAG_MOVER        = 0x0B; // <mjx-mover> (upper-limit / accent container)
export const TAG_UNDER        = 0x0C; // <mjx-under> (underscript / underbrace slot)
export const TAG_OVER         = 0x0D; // <mjx-over> (overscript / overbrace slot)
export const TAG_BOX          = 0x0E; // <mjx-box> (limit intermediate wrapper)
export const TAG_BASE         = 0x0F; // <mjx-base> (anchor base element)
export const TAG_ROW          = 0x10; // <mjx-row> (intermediate row element)
// Scripts & Stretchy Assemblies
export const TAG_SUB          = 0x11; // <mjx-sub> (subscript)
export const TAG_SUP          = 0x12; // <mjx-sup> (superscript)
export const TAG_SCRIPT       = 0x13; // <mjx-script> (MathJax v4 unified script slot)
export const TAG_SPACER       = 0x14; // <mjx-spacer> (inter-script spacer / stretchy spacer)
export const TAG_EXT          = 0x15; // <mjx-ext> (stretchy extender glyph)
// Radicals & Enclosures
export const TAG_SURD         = 0x16; // <mjx-surd> (radical square root sign)
export const TAG_ROOT         = 0x17; // <mjx-root> (degree index slot of \sqrt[n]{x})
// Matrices & Grids
export const TAG_MTR          = 0x18; // <mjx-mtr> (matrix row)
export const TAG_MTD          = 0x19; // <mjx-mtd> (matrix cell)
export const TAG_MSPACE       = 0x1A; // <mjx-mspace> (spacing macro)
export const TAG_TABLE        = 0x1B; // <mjx-mtable> / <mjx-table> / <mjx-itable>
// Grouping & Stretchy Containers
export const TAG_MROW         = 0x1C; // <mjx-mrow> (mrow container)
export const TAG_TEXATOM      = 0x1D; // <mjx-texatom> (texatom wrapper)
export const TAG_STRETCHY_H   = 0x1E; // <mjx-stretchy-h> (horizontal stretchy container)
export const TAG_STRETCHY_V   = 0x1F; // <mjx-stretchy-v> (vertical stretchy container)

