// Composite bitmasks for O(1) membership queries
export const MASK_TRANSPARENT_INTERMEDIATE =
  ChtmlTagMask.MROW |
  ChtmlTagMask.TEXATOM |
  ChtmlTagMask.ROW |
  ChtmlTagMask.BOX |
  ChtmlTagMask.DBOX |
  ChtmlTagMask.DTABLE;

export const MASK_STRETCHY_FRAGMENTS =
  ChtmlTagMask.EXT |
  ChtmlTagMask.SPACER |
  ChtmlTagMask.SURD |
  ChtmlTagMask.LINE;

export const MASK_SLOT_CONTAINERS =
  ChtmlTagMask.NUM |
  ChtmlTagMask.DEN |
  ChtmlTagMask.SUB |
  ChtmlTagMask.SUP |
  ChtmlTagMask.SCRIPT |
  ChtmlTagMask.UNDER |
  ChtmlTagMask.OVER |
  ChtmlTagMask.ROOT |
  ChtmlTagMask.MTD;

export function tagMatchesMask(tagId: number, mask: number): boolean {
  if (tagId < 0 || tagId > 31) return false;
  return ((1 << tagId) & mask) !== 0;
}

export function getTagIdFromNodeName(nodeName: string): number {
  const lower = nodeName.toLowerCase();
  switch (lower) {
    case "mjx-mfrac": return TAG_MFRAC;
    case "mjx-frac": return TAG_FRAC;
    case "mjx-num": return TAG_NUM;
    case "mjx-den": return TAG_DEN;
    case "mjx-dbox": return TAG_DBOX;
    case "mjx-dtable": return TAG_DTABLE;
    case "mjx-line":
    case "mjx-dline": return TAG_LINE;
    case "mjx-dstrut":
    case "mjx-nstrut": return TAG_DSTRUT;
    case "mjx-munderover": return TAG_MUNDEROVER;
    case "mjx-munder": return TAG_MUNDER;
    case "mjx-mover": return TAG_MOVER;
    case "mjx-under": return TAG_UNDER;
    case "mjx-over": return TAG_OVER;
    case "mjx-box": return TAG_BOX;
    case "mjx-base": return TAG_BASE;
    case "mjx-row": return TAG_ROW;
    case "mjx-sub": return TAG_SUB;
    case "mjx-sup": return TAG_SUP;
    case "mjx-script": return TAG_SCRIPT;
    case "mjx-spacer": return TAG_SPACER;
    case "mjx-ext": return TAG_EXT;
    case "mjx-surd": return TAG_SURD;
    case "mjx-root": return TAG_ROOT;
    case "mjx-mtr": return TAG_MTR;
    case "mjx-mtd": return TAG_MTD;
    case "mjx-mspace": return TAG_MSPACE;
    case "mjx-table":
    case "mjx-mtable":
    case "mjx-itable": return TAG_TABLE;
    case "mjx-mrow": return TAG_MROW;
    case "mjx-texatom": return TAG_TEXATOM;
    case "mjx-stretchy-h": return TAG_STRETCHY_H;
    case "mjx-stretchy-v": return TAG_STRETCHY_V;
    default: return TAG_NONE;
  }
}

