export interface CatalogEntry {
  key: string;
  expectedText?: string;
  hexCode?: number; // Scalar uint32 codepoint strictly for 1-glyph atoms
  roleId: number; // 0..15 (ROLE_FUNCTION, ROLE_OPERATOR, etc.)
  priority: number;
  domains: number;
  dialects?: number;
  tier: number; // 0 = standard macro, 1 = Tier 1 bare function, 2 = Tier 2 bare function
  arityNibble?: number; // 4-bit packed arity: (optionalArgs << 2) | mandatoryArgs
  argType?: NumericArgType;
  layoutSlotCode?: number; // 32-bit Big-Endian layout slot code (0x00000000 to 0xFFFFFFFF)
  hasLimits?: boolean; // true for \lim, \sum, \prod (movable limits)
  implicitEnclosure?: boolean; // true for \binom, \pmod (absorbs outer mjx-delims)
  isSpecialCase?: boolean; // true for heterogeneous / non-uniform argument slots
  canonical?: string;
  unicode?: string;
  extensible?: boolean; // true for \overbrace, \underbrace, etc.
  uncolored?: boolean;  // true for \lim, \limsup, etc.

  // Backward-compatibility properties
  arity?: number; // exact mandatory argument count (e.g. 1 for sqrt, 2 for frac)
  hasOptionalBracket?: boolean; // true for macros taking [opt] (e.g. sqrt[n]{x})
}

/**
 * Returns the exact mandatory argument count for a macro.
 * O(1) bitwise evaluation; calls getSpecialMacroArity on escape code 0x3.
 */
export function getMandatoryArgs(entry: CatalogEntry): number {
  if (entry.arityNibble !== undefined) {
    const mand = entry.arityNibble & 0x3;
    if (mand === 3) {
      return getSpecialMacroArity(entry.key);
    }
    return mand;
  }
  return entry.arity ?? 0;
}

/**
 * Returns the optional argument bracket count (0..3).
 * O(1) bitwise evaluation.
 */
export function getOptionalArgs(entry: CatalogEntry): number {
  if (entry.arityNibble !== undefined) {
    return (entry.arityNibble >> 2) & 0x3;
  }
  return entry.hasOptionalBracket ? 1 : 0;
}

/**
 * Resolves exact arity for exotic macros taking >= 3 mandatory arguments.
 */
export function getSpecialMacroArity(key: string): number {
  switch (key) {
    case "\\genfrac": return 6;
    case "\\sideset": return 3;
    default: return 3;
  }
}

/**
 * Extracts expected MathJax CHTML Tag ID for child argument slot i (0 to 3)
 * using 32-bit Big-Endian byte ordering:
 * Slot 0 = Bits 31..24, Slot 1 = Bits 23..16, Slot 2 = Bits 15..8, Slot 3 = Bits 7..0.
 * O(1) single bit-shift instruction (~0.2 ns), zero heap allocation.
 */
export function getExpectedChildTag(entry: CatalogEntry, slotIndex: number): number {
  if (!entry.layoutSlotCode || slotIndex < 0 || slotIndex > 3) {
    return TAG_NONE;
  }
  return (entry.layoutSlotCode >>> (24 - 8 * slotIndex)) & 0xFF;
}

export interface CatalogMatch {
  length: number;
  entry: CatalogEntry;
}

const N = 9342;
const MASK = 4095;

// 32-bit FNV-1a hash
function fnv1a(str: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

